values ((select id from trilhas where ordem = 1), 1, 'm1', 'Renda extra pela internet', 5, 'zmISrAl8h24', null, 'Renda extra com aplicativos', 'Serasa Ensina', 'Aplicativos e plataformas online podem render uma renda extra, mas é preciso conferir se são seguros e desconfiar de promessas de lucro alto e fácil.', 'classificar', 'Parece seguro ou é sinal de alerta?', 'Toque na opção de cada situação.', '{"opcoes":["Parece seguro","Sinal de alerta"],"itens":[["Promete lucro muito alto e fácil",1],["Pede um pagamento antecipado para liberar seus ganhos",1],["Tem CNPJ, regras claras e um canal de atendimento que você consegue conferir",0],["Pede a senha do seu banco",1],["Não cobra nada para participar e explica como o pagamento funciona",0]]}'::jsonb, array['Aplicativos e plataformas online podem gerar renda extra.', 'Antes de se cadastrar, confira se a plataforma é segura e verdadeira.', 'Desconfie de promessas de lucro muito alto e fácil.']);

values ((select id from trilhas where ordem = 1), 2, 'm2', 'O ciclo da dívida', 5, 'UEiBsd_nmTA', null, 'O ciclo da dívida', 'Serasa Ensina', 'O ciclo da dívida passa pelo atraso no pagamento, pela cobrança da empresa credora e pela possível negativação, quando a Serasa entra para comunicar e registrar informações de crédito.', 'classificar', 'Quem faz o quê?', 'Toque em quem é responsável por cada ação.', '{"opcoes":["Empresa credora","Serasa"],"itens":[["Concedeu o crédito e cobra a dívida",0],["Solicita a negativação da dívida",0],["Comunica o consumidor sobre a possível negativação",1],["Registra as informações de crédito",1]]}'::jsonb, array['O atraso no pagamento é uma das primeiras etapas do ciclo da dívida.', 'Quem solicita a negativação é a empresa credora.', 'A Serasa comunica a possível negativação e registra informações de crédito.']);

values ((select id from trilhas where ordem = 1), 3, 'm3', 'Atrasada, negativada ou caducada?', 5, 'CkwxlovFIa0', null, 'Dívida atrasada, negativada ou caduca: qual a diferença?', 'Serasa Ensina', 'Dívida atrasada é a que passou do vencimento. A negativada é registrada nos birôs. A caducada pode deixar de aparecer nos birôs depois de cinco anos, mas a pendência continua com a empresa.', 'classificar', 'Qual é qual?', 'Toque no tipo de dívida de cada situação.', '{"opcoes":["Atrasada","Negativada","Caducada"],"itens":[["Venceu ontem e ainda não foi paga",0],["Seu nome foi registrado nos birôs por causa da dívida",1],["Passou de cinco anos e deixou de aparecer nos birôs, mas a pendência segue com a empresa",2],["Pode gerar juros enquanto não for paga",0]]}'::jsonb, array['Atrasada: não foi paga até o vencimento.', 'Negativada: o nome foi registrado nos birôs de crédito.', 'Caducada: pode sair dos birôs depois de cinco anos, mas a pendência continua com a empresa.']);

values ((select id from trilhas where ordem = 1), 4, 'm4', 'O que é amortização?', 5, '7Ib1rTuxUpk', null, 'O que é amortização? (Falando Dinheirês)', 'Serasa Ensina', 'Amortizar é pagar uma parte da dívida para reduzir o valor devido, diminuindo o saldo devedor.', 'amortizar', 'Veja o saldo devedor diminuir', 'Mude os valores e veja quanto falta pagar.', null, array['Amortizar é reduzir o valor devido por meio de pagamentos.', 'A amortização está ligada à redução de uma dívida.', 'Ao amortizar, o saldo devedor pode diminuir.']);

values ((select id from trilhas where ordem = 1), 5, 'm5', 'Juros de mora', 5, 'Yic1w81yBq8', null, 'Juros de mora (Falando Dinheirês)', 'Serasa Ensina', 'Juros de mora são cobrados pelo atraso no pagamento de uma conta e podem aumentar quanto maior for o tempo de atraso.', 'mora', 'Veja o atraso custando mais', 'Mexa nos dias de atraso e compare o valor final.', null, array['Juros de mora são cobrados pelo atraso no pagamento.', 'Quanto maior o atraso, maior pode ser o valor dos juros.', 'Pagar dentro do prazo evita essa cobrança.']);

